$keep=@('judas_editor.exe','judas.exe','judas_export.exe','judas_joint_tests.exe','judas_collision_geometry_tests.exe','judas_rigid_motion_tests.exe','judas_streaming_tests.exe','judas_scalability_tests.exe','judas_production_fluid_tests.exe','judas_physical_animation_tests.exe','judas_balance_controller_tests.exe','judas_balance_lab_tests.exe','judas_character_motor_tests.exe','judas_navigation_bake.exe','judas_terrain_pipeline_tests.exe')
$files=Get-ChildItem -LiteralPath C:\JudasValidation\Build\Release -File -Filter *.exe | Where-Object {$keep -notcontains $_.Name} | ForEach-Object {[pscustomobject]@{path=$_.FullName;bytes=$_.Length;sha256=(Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash.ToLower()}}
[pscustomobject]@{free=(Get-PSDrive C).Free;disposableUnchangedTestExecutables=$files;bytes=($files|Measure-Object -Property bytes -Sum).Sum}|ConvertTo-Json -Depth 5 -Compress
